import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Galerie","description":"Einträge als Karten mit Bildern darstellen.","frontmatter":{"title":"Galerie","description":"Einträge als Karten mit Bildern darstellen."},"headers":[],"relativePath":"ansichten/galerie.md","filePath":"ansichten/galerie.md","lastUpdated":1786170655000}'),a={name:"ansichten/galerie.md"};function l(s,e,d,o,h,c){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h1><p>Die <strong>Galerie</strong> zeigt Einträge als Karten — auf Wunsch mit Bild.</p><p>Die Oberfläche beschreibt sie als <em>Übersicht auf deine Daten</em>: <em>Stelle deine Daten als Karten einer Galerie dar.</em></p><p><strong>Geeignet für:</strong> Produktkataloge, Personenverzeichnisse, Immobilien, Materialien, Portfolios — alles, wo das Bild wichtiger ist als die Tabellenzeile.</p><h2 id="galerie-anlegen" tabindex="-1">Galerie anlegen <a class="header-anchor" href="#galerie-anlegen" aria-label="Permalink to &quot;Galerie anlegen&quot;">​</a></h2><ol><li>Wählen Sie unter dem Grid <strong>Ansicht erstellen</strong>.</li><li>Wählen Sie <strong>Galerie</strong>.</li></ol><p>Anders als Kanban, Kalender und Karte braucht die Galerie <strong>keine besondere Spalte</strong>. Sie funktioniert sofort — mit Bildern sieht sie nur besser aus.</p><h2 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h2><p>Über <strong>Einstellungen</strong>:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Auswahl</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Bild</strong></td><td><em>Erstes Bild</em> / <em>Kein Bild</em></td><td>Ob und welches Bild auf der Karte erscheint</td></tr><tr><td><strong>Kartengröße</strong></td><td><em>Klein</em> / <em>Mittel</em> / <em>Groß</em></td><td>Größe der Karten und damit Anzahl je Zeile</td></tr><tr><td><strong>Feld Icon</strong></td><td>an/aus</td><td>Zeigt das Symbol des Spaltentyps vor jedem Wert</td></tr><tr><td><strong>Feld Name</strong></td><td>an/aus</td><td>Zeigt den Feldnamen vor jedem Wert</td></tr><tr><td><strong>URL-Felder als Buttons</strong></td><td>an/aus</td><td>Stellt Weblink-Felder als Schaltflächen dar</td></tr></tbody></table><h3 id="bild" tabindex="-1">Bild <a class="header-anchor" href="#bild" aria-label="Permalink to &quot;Bild&quot;">​</a></h3><p><strong>Erstes Bild</strong> nimmt das erste Bild aus einer Spalte vom Typ <strong>Dateien</strong>. Enthält der Eintrag kein Bild, bleibt die Fläche leer.</p><p><strong>Kein Bild</strong> zeigt reine Textkarten — sinnvoll, wenn es keine Bilder gibt, die Kartendarstellung aber trotzdem übersichtlicher ist als eine Tabelle.</p><div class="tip custom-block"><p class="custom-block-title">Bilder gehören nach vorn</p><p>Die Galerie nimmt das <strong>erste</strong> Bild des Dateifeldes. Wollen Sie steuern, welches das ist, sortieren Sie die Anhänge im Eintrag entsprechend — oder legen Sie eine eigene Spalte „Titelbild&quot; an, die nur ein Bild enthält.</p></div><h3 id="kartengroße" tabindex="-1">Kartengröße <a class="header-anchor" href="#kartengroße" aria-label="Permalink to &quot;Kartengröße&quot;">​</a></h3><p><em>Klein</em> zeigt viele Einträge auf einen Blick, <em>Groß</em> stellt das Bild in den Vordergrund. <em>Mittel</em> ist der Kompromiss.</p><div class="tip custom-block"><p class="custom-block-title">Größe nach Verwendung wählen</p><p>Für ein <a href="/seiten/portal-veroeffentlichen">Portal</a>, das Kunden einen Katalog zeigt, ist <em>Groß</em> meist richtig. Für die interne Pflege vieler Einträge ist <em>Klein</em> praktischer.</p></div><h3 id="feld-icon-und-feld-name" tabindex="-1">Feld Icon und Feld Name <a class="header-anchor" href="#feld-icon-und-feld-name" aria-label="Permalink to &quot;Feld Icon und Feld Name&quot;">​</a></h3><p>Beide Schalter steuern, wie viel Beiwerk je Wert erscheint. Ausgeschaltet wirken die Karten aufgeräumter, dafür ist weniger klar, welcher Wert wozu gehört.</p><div class="tip custom-block"><p class="custom-block-title">Für Portale beides ausschalten</p><p>Interne Feldnamen wie <code>status_2</code> oder <code>Preis_netto</code> sind für Außenstehende verwirrend. Ohne Feldnamen und Symbole sieht eine veröffentlichte Galerie deutlich professioneller aus.</p></div><h3 id="url-felder-als-buttons" tabindex="-1">URL-Felder als Buttons <a class="header-anchor" href="#url-felder-als-buttons" aria-label="Permalink to &quot;URL-Felder als Buttons&quot;">​</a></h3><p>Verwandelt Felder vom Typ <strong>Weblink</strong> in Schaltflächen statt in reinen Text — praktisch für „Zum Shop&quot;, „Datenblatt&quot;, „Mehr erfahren&quot;.</p><h2 id="welche-felder-auf-der-karte-erscheinen" tabindex="-1">Welche Felder auf der Karte erscheinen <a class="header-anchor" href="#welche-felder-auf-der-karte-erscheinen" aria-label="Permalink to &quot;Welche Felder auf der Karte erscheinen&quot;">​</a></h2><p>Wie bei allen Ansichten steuern Sie das über die sichtbaren Spalten. Ausgeblendete Spalten erscheinen nicht auf der Karte.</p><p>→ <a href="/ansichten/spalten-verwalten">Spalten verwalten</a></p><div class="tip custom-block"><p class="custom-block-title">Weniger Felder, bessere Karten</p><p>Eine Galeriekarte mit fünfzehn Feldern ist keine Galerie mehr, sondern eine schmale Tabelle. Blenden Sie alles aus, was nicht auf den ersten Blick gebraucht wird.</p></div><h2 id="filter-und-sortierung" tabindex="-1">Filter und Sortierung <a class="header-anchor" href="#filter-und-sortierung" aria-label="Permalink to &quot;Filter und Sortierung&quot;">​</a></h2><p>Wirken wie in jeder Ansicht. Die Sortierung bestimmt die Reihenfolge der Karten.</p><p>→ <a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></li><li><a href="/ansichten/spalten-verwalten">Spalten verwalten</a></li><li><a href="/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></li></ul>',31)])])}const m=t(a,[["render",l]]);export{g as __pageData,m as default};
